<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Notification Preferences</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #0b1220;
        --panel: #111a2c;
        --panel-2: #162238;
        --text: #e7eefc;
        --muted: #9fb0d0;
        --border: #2c3d5e;
        --accent: #7c9cff;
        --accent-strong: #9ab1ff;
        --shadow: 0 24px 64px rgba(0, 0, 0, 0.35);
        --radius: 20px;
      }

      * {
        box-sizing: border-box;
      }

      html {
        color: var(--text);
        background:
          radial-gradient(circle at top, #16233b 0%, transparent 42%),
          linear-gradient(180deg, #0b1220 0%, #09101b 100%);
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        line-height: 1.5;
      }

      a.skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 10;
        padding: 0.75rem 1rem;
        border-radius: 999px;
        background: var(--accent);
        color: #08101d;
        font-weight: 700;
        text-decoration: none;
        transform: translateY(-180%);
      }

      a.skip-link:focus {
        transform: translateY(0);
        outline: 3px solid #ffffff;
        outline-offset: 3px;
      }

      main {
        display: grid;
        place-items: center;
        min-height: 100vh;
        padding: 5rem 1.25rem 2rem;
      }

      .card {
        width: min(100%, 40rem);
        padding: clamp(1.5rem, 4vw, 2.5rem);
        border: 1px solid var(--border);
        border-radius: var(--radius);
        background: linear-gradient(180deg, rgba(17, 26, 44, 0.96), rgba(12, 18, 31, 0.96));
        box-shadow: var(--shadow);
      }

      h1 {
        margin: 0 0 0.5rem;
        font-size: clamp(2rem, 4vw, 2.75rem);
        line-height: 1.1;
      }

      .lead {
        margin: 0 0 2rem;
        color: var(--muted);
      }

      form {
        display: grid;
        gap: 1.5rem;
      }

      .form-field {
        padding: 1.25rem;
        border: 1px solid var(--border);
        border-radius: 1.25rem;
        background: linear-gradient(180deg, rgba(22, 34, 56, 0.94), rgba(17, 26, 44, 0.94));
      }

      fieldset {
        margin: 0;
        padding: 0;
        border: 0;
      }

      legend {
        padding: 0;
        font-size: 1.1rem;
        font-weight: 700;
      }

      .required {
        margin-left: 0.35rem;
        color: var(--accent-strong);
        font-size: 0.95em;
      }

      .options {
        display: grid;
        gap: 0.8rem;
        margin-top: 1rem;
      }

      label.option {
        display: flex;
        align-items: center;
        gap: 0.9rem;
        padding: 0.95rem 1rem;
        border: 1px solid var(--border);
        border-radius: 1rem;
        background: rgba(11, 18, 32, 0.75);
        cursor: pointer;
        transition: border-color 160ms ease, background-color 160ms ease, transform 160ms ease;
      }

      label.option:hover {
        border-color: #40557d;
        background: rgba(18, 28, 48, 0.88);
      }

      label.option:has(input:focus-visible) {
        outline: 3px solid var(--accent);
        outline-offset: 2px;
      }

      input[type="radio"] {
        width: 1.1rem;
        height: 1.1rem;
        margin: 0;
        accent-color: var(--accent);
        flex: 0 0 auto;
      }

      .option-text {
        font-size: 1rem;
      }

      .actions {
        display: flex;
        justify-content: flex-end;
      }

      button {
        border: 0;
        border-radius: 999px;
        padding: 0.95rem 1.4rem;
        background: linear-gradient(180deg, var(--accent-strong), var(--accent));
        color: #08101d;
        font: inherit;
        font-weight: 700;
        cursor: pointer;
        box-shadow: 0 10px 24px rgba(124, 156, 255, 0.28);
        transition: transform 160ms ease, box-shadow 160ms ease;
      }

      button:hover {
        transform: translateY(-1px);
        box-shadow: 0 14px 28px rgba(124, 156, 255, 0.34);
      }

      button:focus-visible {
        outline: 3px solid #ffffff;
        outline-offset: 3px;
      }

      #status {
        min-height: 1.5rem;
        margin: 0;
        color: var(--accent-strong);
        font-weight: 600;
      }

      @media (max-width: 480px) {
        main {
          padding-inline: 0.75rem;
        }

        .card {
          padding: 1.25rem;
        }

        .actions {
          justify-content: stretch;
        }

        button {
          width: 100%;
        }
      }

      @media (forced-colors: active) {
        :root {
          --bg: Canvas;
          --panel: Canvas;
          --panel-2: Canvas;
          --text: CanvasText;
          --muted: CanvasText;
          --border: ButtonBorder;
          --accent: ButtonText;
          --accent-strong: ButtonText;
        }

        body,
        .card,
        .form-field,
        label.option,
        button {
          forced-color-adjust: auto;
        }

        label.option:has(input:focus-visible),
        button:focus-visible,
        a.skip-link:focus {
          outline-color: Highlight;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <main id="main-content">
      <section class="card" aria-labelledby="page-title">
        <h1 id="page-title">Notification Preferences</h1>
        <p class="lead">Choose how you want to hear from us.</p>

        <form id="preferences-form" novalidate>
          <div class="form-field">
            <fieldset>
              <legend>
                How do you prefer to receive notifications?
                <span class="required" aria-hidden="true">*</span>
              </legend>
              <div class="options" role="radiogroup" aria-labelledby="notification-legend">
                <span id="notification-legend" class="sr-only">How do you prefer to receive notifications?</span>
                <label class="option">
                  <input type="radio" name="notification-preference" value="Email" required />
                  <span class="option-text">Email</span>
                </label>
                <label class="option">
                  <input type="radio" name="notification-preference" value="SMS" />
                  <span class="option-text">SMS</span>
                </label>
                <label class="option">
                  <input type="radio" name="notification-preference" value="Push Notifications" />
                  <span class="option-text">Push Notifications</span>
                </label>
              </div>
            </fieldset>
          </div>

          <div class="actions">
            <button type="submit">Submit</button>
          </div>
          <p id="status" aria-live="polite"></p>
        </form>
      </section>
    </main>

    <script>
      const form = document.getElementById("preferences-form");
      const status = document.getElementById("status");
      const radios = Array.from(form.elements["notification-preference"]);

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        const selected = radios.find((radio) => radio.checked);
        if (!selected) {
          status.textContent = "Please select a notification preference before submitting.";
          radios[0].focus();
          return;
        }

        status.textContent = `You selected ${selected.value}.`;
      });
    </script>
  </body>
</html>
